// function passwordStrength(password) mein string do
// <6 chars: "Weak", 6-10: "Medium", >10 with special char: "Strong"
// >10 bina special char: "Medium"

solution:
function passwordStrength(password) {
  if (password.length < 6) return "Weak"
  if (password.length > 10) {
    if (/[^a-zA-Z0-9]/.test(password)) return "Strong"
    else return "Medium"
  }
  return "Medium"
}
